testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Animazioni 3D importate",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var current_speed: float = 3.5
	var max_walk_speed: float = 5.0
	var blend_pos: float = current_speed / max_walk_speed
	return blend_pos
",
   "domanda": "Quanto vale `blend_pos` alla fine?",
   "spiegazione": "`current_speed` (3.5) diviso `max_walk_speed` (5.0) dà 0.7. Questo valore numerico viene usato tipicamente nello script per aggiornare il parametro `blend_position` di un `AnimationNodeBlendSpace1D`."
  },
  {
   "codice": "extends RefCounted


func run():
	var velocity_y: float = -2.0
	var is_grounded: bool = false
	var is_falling: bool = not is_grounded and velocity_y < 0.0
	return is_falling
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`is_grounded` è falso, quindi `not is_grounded` è vero. Anche `velocity_y < 0.0` è vero perché -2.0 è minore di zero. Essendo entrambe vere con l'operatore `and`, `is_falling` è `true`."
  },
  {
   "codice": "extends RefCounted


func run():
	var anim_path: String = "parameters/StateMachine/playback"
	return anim_path.contains("StateMachine")
",
   "domanda": "La funzione restituisce `true` o `false`?",
   "spiegazione": "Il metodo `contains()` verifica se la stringa "StateMachine" è presente all'interno di `anim_path`. Poiché il percorso punta esattamente alla macchina a stati dell'AnimationTree, restituisce `true`."
  },
  {
   "codice": "extends RefCounted


func run():
	var speed: float = 6.2
	var run_threshold: float = 5.0
	var is_running: bool = speed > run_threshold
	return is_running
",
   "domanda": "Quanto vale `is_running` alla fine?",
   "spiegazione": "`speed` vale 6.2, che supera la soglia di corsa `run_threshold` fissata a 5.0. La condizione di confronto è verificata, quindi la variabile diventa `true`."
  },
  {
   "codice": "extends RefCounted


func run():
	var input_dir: float = -1.0
	var speed_multiplier: float = 2.0
	var blend_value: float = input_dir * speed_multiplier
	return blend_value
",
   "domanda": "Quanto vale `blend_value` alla fine?",
   "spiegazione": "Moltiplicando -1.0 per 2.0 si ottiene -2.0. Un valore negativo nel BlendSpace1D permette di gestire le animazioni di movimento all'indietro."
  }
 ]
}
